-- Rollback-only synthetic global-admin lifecycle and provisioning regression.
BEGIN;
SET LOCAL search_path=extensions,public,pg_temp;
SELECT no_plan();
INSERT INTO auth.users(id,email,raw_app_meta_data,email_confirmed_at,encrypted_password) VALUES
 ('14600000-0000-4000-8000-000000000001','platform146@example.test','{"_invite_provisioned":true}',now(),'synthetic-owned-hash'),
 ('14600000-0000-4000-8000-000000000002','owner146@example.test','{"_invite_provisioned":true}',now(),'synthetic-owned-hash'),
 ('14600000-0000-4000-8000-000000000003','foreign146@example.test','{"_invite_provisioned":true}',now(),'synthetic-owned-hash'),
 ('14600000-0000-4000-8000-000000000004','member146@example.test','{"_invite_provisioned":true}',now(),'synthetic-owned-hash'),
 ('14600000-0000-4000-8000-000000000005','protected146@example.test','{"_invite_provisioned":true}',now(),'synthetic-owned-hash');
CREATE TEMP TABLE platform146_tenants(kind text PRIMARY KEY,id uuid);
INSERT INTO platform146_tenants VALUES
 ('own',(public.provision_company_atomic('14600000-0000-4000-8000-000000000002','{"name":"Platform target fixture","slug":"platform-target146","domain":"platform146.example.test"}')->>'id')::uuid),
 ('foreign',(public.provision_company_atomic('14600000-0000-4000-8000-000000000003','{"name":"Platform foreign fixture","slug":"platform-foreign146","domain":"foreign146.example.test"}')->>'id')::uuid);
INSERT INTO public.users(id,auth_user_id,tenant_id,email,role,status,must_change_password) VALUES
 ('14600000-0000-4000-8000-000000000101','14600000-0000-4000-8000-000000000001',(SELECT id FROM platform146_tenants WHERE kind='foreign'),'platform146@example.test','admin','active',false),
 ('14600000-0000-4000-8000-000000000104','14600000-0000-4000-8000-000000000004',(SELECT id FROM platform146_tenants WHERE kind='own'),'member146@example.test','accountant','active',false),
 ('14600000-0000-4000-8000-000000000105','14600000-0000-4000-8000-000000000005',(SELECT id FROM platform146_tenants WHERE kind='own'),'protected146@example.test','supervisor','active',false);
INSERT INTO public.platform_admins(user_id,email) VALUES('14600000-0000-4000-8000-000000000001','platform146@example.test'),('14600000-0000-4000-8000-000000000005','protected146@example.test');
INSERT INTO public.tenant_memberships(tenant_id,user_id) VALUES((SELECT id FROM platform146_tenants WHERE kind='own'),'14600000-0000-4000-8000-000000000104');
INSERT INTO public.user_role_assignments(tenant_id,user_id,role_id) SELECT (SELECT id FROM platform146_tenants WHERE kind='own'),'14600000-0000-4000-8000-000000000104',id FROM public.roles WHERE tenant_id=(SELECT id FROM platform146_tenants WHERE kind='own') AND name='accountant';
CREATE TEMP TABLE platform146_owner AS SELECT id AS user_id,version FROM public.users WHERE auth_user_id='14600000-0000-4000-8000-000000000002';
GRANT SELECT ON platform146_owner TO authenticated;
CREATE TEMP TABLE platform146_results(kind text PRIMARY KEY,result jsonb);
GRANT SELECT ON platform146_tenants TO authenticated,anon,service_role;
GRANT ALL ON platform146_results TO authenticated,service_role;
SELECT is((SELECT count(*) FROM public.tenant_memberships WHERE tenant_id=(SELECT id FROM platform146_tenants WHERE kind='own') AND user_id='14600000-0000-4000-8000-000000000101'),0::bigint,'platform authority has no membership in the target tenant');
SELECT ok(NOT has_schema_privilege('authenticated','platform_management_private','USAGE') AND NOT has_table_privilege('service_role','platform_management_private.creation_requests','SELECT'),'private reservations are not exposed through Data API grants');
SELECT is((SELECT count(*)::integer FROM pg_proc WHERE oid IN('public.mutate_platform_user(text,uuid,bigint,jsonb)'::regprocedure,'public.reserve_platform_user(uuid,uuid,text,text,text)'::regprocedure,'public.finalize_platform_user(uuid)'::regprocedure,'public.issue_platform_user_invite(uuid,uuid,text,text,text,uuid,text,timestamptz)'::regprocedure) AND prosecdef AND 'search_path=""'=ANY(proconfig)),4,'all platform RPCs pin definer search_path');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"14600000-0000-4000-8000-000000000002","aal":"aal2"}',true);
SELECT throws_ok($$SELECT public.mutate_platform_user('role','14600000-0000-4000-8000-000000000104',1,'{"role":"supervisor","reason":"Tenant GM is not platform admin"}')$$,'42501','PUM_FORBIDDEN','ordinary tenant GM cannot invoke cross-tenant platform authority');
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"14600000-0000-4000-8000-000000000001","aal":"aal1"}',true);
SELECT throws_ok($$SELECT public.mutate_platform_user('role','14600000-0000-4000-8000-000000000104',1,'{"role":"supervisor","reason":"Insufficient assurance"}')$$,'42501','PUM_FORBIDDEN','platform membership without verified AAL2 cannot mutate users');
SELECT set_config('request.jwt.claims','{"role":"service_role","sub":"14600000-0000-4000-8000-000000000001","aal":"aal2"}',true);
SELECT throws_ok($$SELECT public.mutate_platform_user('role','14600000-0000-4000-8000-000000000104',1,'{"role":"supervisor","reason":"Service JWT impersonation"}')$$,'42501','PUM_FORBIDDEN','service JWT cannot impersonate an authenticated platform caller');
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"14600000-0000-4000-8000-000000000001","aal":"aal2"}',true);
SELECT throws_ok($$SELECT public.mutate_platform_user('status','14600000-0000-4000-8000-000000000101',1,'{"status":"inactive","reason":"Self lockout forbidden"}')$$,'42501','PUM_PROTECTED','platform administrator cannot mutate own account');
SELECT throws_ok($$SELECT public.mutate_platform_user('role','14600000-0000-4000-8000-000000000105',1,'{"role":"accountant","reason":"Protected platform administrator"}')$$,'42501','PUM_PROTECTED','another platform administrator account remains protected');
SELECT throws_ok($$SELECT public.mutate_platform_user('role','14600000-0000-4000-8000-000000000104',1,'{"role":"general_manager","reason":"Owner promotion out of scope"}')$$,'22023','PUM_ROLE','platform endpoint does not bypass the owner appointment policy');
SELECT throws_ok($$SELECT public.mutate_platform_user('role','14600000-0000-4000-8000-000000000999',(SELECT version FROM platform146_owner),'{"role":"supervisor","reason":"Last owner demotion forbidden"}')$$,'P0002','PUM_NOT_FOUND','unknown target is never treated as a successful update');
SELECT throws_ok($$SELECT public.mutate_platform_user('status',(SELECT user_id FROM platform146_owner),(SELECT version FROM platform146_owner),'{"status":"inactive","reason":"Last owner must remain active"}'::jsonb)$$,'55000','PUM_LAST_OWNER','last active general manager cannot be deactivated');
SELECT throws_ok($$SELECT public.mutate_platform_user('role',(SELECT user_id FROM platform146_owner),(SELECT version FROM platform146_owner),'{"role":"supervisor","reason":"Last owner must remain active"}'::jsonb)$$,'55000','PUM_LAST_OWNER','last active general manager cannot be demoted');
SELECT lives_ok($$SELECT public.mutate_platform_user('role','14600000-0000-4000-8000-000000000104',1,'{"role":"supervisor","reason":"Change responsibility safely"}')$$,'global admin manages another tenant without tenant membership');
RESET ROLE;
SELECT is((SELECT role::text FROM public.users WHERE id='14600000-0000-4000-8000-000000000104'),'supervisor','role change persists the selected supported role');
SELECT is((SELECT version FROM public.users WHERE id='14600000-0000-4000-8000-000000000104'),2::bigint,'atomic user mutation advances the expected version');
SELECT is((SELECT count(*) FROM public.user_role_assignments WHERE user_id='14600000-0000-4000-8000-000000000104' AND revoked_at IS NULL AND deleted_at IS NULL),1::bigint,'role replacement leaves one active assignment');
SELECT is((SELECT count(*) FROM public.user_role_assignments WHERE user_id='14600000-0000-4000-8000-000000000104' AND revoked_at IS NOT NULL),1::bigint,'role replacement preserves the prior assignment history');
SELECT ok(EXISTS(SELECT 1 FROM public.user_role_assignments a JOIN public.roles r ON r.id=a.role_id WHERE a.user_id='14600000-0000-4000-8000-000000000104' AND a.revoked_at IS NULL AND r.name='supervisor' AND a.assigned_by='14600000-0000-4000-8000-000000000001'),'new assignment binds the target tenant role and platform actor');
SELECT is((SELECT count(*) FROM public.audit_log WHERE entity_id='14600000-0000-4000-8000-000000000104' AND action='platform_user_role'),1::bigint,'role change and audit commit exactly once');
SELECT ok(NOT EXISTS(SELECT 1 FROM public.audit_log WHERE entity_id='14600000-0000-4000-8000-000000000104' AND (coalesce(old_values,'{}')||coalesce(new_values,'{}')) ?| ARRAY['email','full_name','password','reason','ip_address']),'platform audit payload never copies names/email/password/freeform reason');
CREATE FUNCTION pg_temp.fail_platform146_audit() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF NEW.module='platform_admin' THEN RAISE EXCEPTION 'Synthetic platform audit fault';END IF;RETURN NEW;END;$$;
CREATE TRIGGER fail_platform146_audit BEFORE INSERT ON public.audit_log FOR EACH ROW EXECUTE FUNCTION pg_temp.fail_platform146_audit();
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"14600000-0000-4000-8000-000000000001","aal":"aal2"}',true);
SELECT throws_ok($$SELECT public.mutate_platform_user('role','14600000-0000-4000-8000-000000000104',1,'{"role":"admin","reason":"Stale version cannot overwrite"}')$$,'40001','PUM_STALE','stale expected version cannot overwrite a reviewed role change');
SELECT throws_ok($$SELECT public.mutate_platform_user('role','14600000-0000-4000-8000-000000000104',2,'{"role":"accountant","reason":"Audit failure must rollback"}')$$,'P0001','Synthetic platform audit fault','audit failure aborts role and assignment replacement');
RESET ROLE;
SELECT is((SELECT role::text FROM public.users WHERE id='14600000-0000-4000-8000-000000000104'),'supervisor','failed audit preserves the previous role');
SELECT is((SELECT version FROM public.users WHERE id='14600000-0000-4000-8000-000000000104'),2::bigint,'failed audit preserves the source version');
SELECT is((SELECT count(*) FROM public.user_role_assignments WHERE user_id='14600000-0000-4000-8000-000000000104' AND revoked_at IS NULL),1::bigint,'failed audit leaves one unchanged active assignment');
DROP TRIGGER fail_platform146_audit ON public.audit_log;
UPDATE public.roles SET deleted_at=now() WHERE tenant_id=(SELECT id FROM platform146_tenants WHERE kind='own') AND name='platform_coordinator';
SET LOCAL ROLE authenticated;
SELECT throws_ok($$SELECT public.mutate_platform_user('role','14600000-0000-4000-8000-000000000104',2,'{"role":"platform_coordinator","reason":"Archived preset cannot be assigned"}')$$,'22023','PUM_ROLE','an archived target-tenant preset cannot be assigned');
SELECT throws_ok($$SELECT public.mutate_platform_user('archive','14600000-0000-4000-8000-000000000104',2,'{"reason":"Do not archive active account"}')$$,'55000','PUM_DEACTIVATE_FIRST','active account must be deactivated before archive');
SELECT lives_ok($$SELECT public.mutate_platform_user('status','14600000-0000-4000-8000-000000000104',2,'{"status":"inactive","reason":"Deactivate account safely"}')$$,'platform admin can deactivate an ordinary account');
RESET ROLE;
UPDATE public.roles SET deleted_at=now() WHERE tenant_id=(SELECT id FROM platform146_tenants WHERE kind='own') AND name='supervisor';
SET LOCAL ROLE authenticated;
SELECT throws_ok($$SELECT public.mutate_platform_user('status','14600000-0000-4000-8000-000000000104',3,'{"status":"active","reason":"Archived role cannot be reactivated"}')$$,'22023','PUM_ROLE','activation requires a currently configured active target tenant role');
RESET ROLE;
UPDATE public.roles SET deleted_at=NULL WHERE tenant_id=(SELECT id FROM platform146_tenants WHERE kind='own') AND name='supervisor';
CREATE TRIGGER fail_platform146_audit BEFORE INSERT ON public.audit_log FOR EACH ROW EXECUTE FUNCTION pg_temp.fail_platform146_audit();
SET LOCAL ROLE authenticated;
SELECT throws_ok($$SELECT public.mutate_platform_user('archive','14600000-0000-4000-8000-000000000104',3,'{"reason":"Archive atomic rollback proof"}')$$,'P0001','Synthetic platform audit fault','failed archive audit rolls back profile, membership and assignments');
RESET ROLE;
SELECT ok((SELECT deleted_at IS NULL AND version=3 FROM public.users WHERE id='14600000-0000-4000-8000-000000000104'),'failed archive retains the unarchived source version');
SELECT is((SELECT count(*) FROM public.tenant_memberships WHERE user_id='14600000-0000-4000-8000-000000000104' AND deleted_at IS NULL),1::bigint,'failed archive preserves active membership');
DROP TRIGGER fail_platform146_audit ON public.audit_log;
SET LOCAL ROLE authenticated;
SELECT lives_ok($$SELECT public.mutate_platform_user('archive','14600000-0000-4000-8000-000000000104',3,'{"reason":"Archive inactive account safely"}')$$,'inactive account archives atomically');
RESET ROLE;
SELECT ok((SELECT deleted_at IS NOT NULL AND version=4 FROM public.users WHERE id='14600000-0000-4000-8000-000000000104'),'archive persists a versioned tombstone');
SELECT is((SELECT count(*) FROM public.user_role_assignments WHERE user_id='14600000-0000-4000-8000-000000000104' AND revoked_at IS NULL AND deleted_at IS NULL),0::bigint,'archive retires all active role assignments');
SELECT is((SELECT count(*) FROM public.tenant_memberships WHERE user_id='14600000-0000-4000-8000-000000000104' AND deleted_at IS NULL),0::bigint,'archive retires active tenant memberships');
SELECT is((SELECT count(*) FROM public.platform_admins WHERE user_id IN('14600000-0000-4000-8000-000000000001','14600000-0000-4000-8000-000000000005')),2::bigint,'user lifecycle never changes platform administrator rows');
SET LOCAL ROLE authenticated;
SELECT throws_ok($$SELECT public.mutate_platform_user('status','14600000-0000-4000-8000-000000000104',4,'{"status":"active","reason":"Archived user must remain archived"}')$$,'P0002','PUM_NOT_FOUND','archived account cannot be silently reactivated');

-- Initial-password provisioning reserves one owned Auth UUID without storing a password.
INSERT INTO platform146_results VALUES('reserved',public.reserve_platform_user('14600000-0000-4000-8000-000000000090',(SELECT id FROM platform146_tenants WHERE kind='own'),'created146@example.test','accountant','Created synthetic user'));
SELECT is(public.reserve_platform_user('14600000-0000-4000-8000-000000000090',(SELECT id FROM platform146_tenants WHERE kind='own'),'created146@example.test','accountant','Created synthetic user')->>'auth_user_id',(SELECT result->>'auth_user_id' FROM platform146_results WHERE kind='reserved'),'retry reserves exactly the same Auth identity');
SELECT throws_ok($$SELECT public.reserve_platform_user('14600000-0000-4000-8000-000000000090',(SELECT id FROM platform146_tenants WHERE kind='own'),'created146@example.test','supervisor','Created synthetic user')$$,'22023','PUM_REQUEST_MISMATCH','a request nonce cannot be rebound to another role');
SELECT throws_ok($$SELECT public.reserve_platform_user('14600000-0000-4000-8000-000000000091',(SELECT id FROM platform146_tenants WHERE kind='own'),'owner146@example.test','accountant',NULL)$$,'23505','PUM_EMAIL_EXISTS','new creation cannot adopt an arbitrary existing email');
SELECT throws_ok($$SELECT public.finalize_platform_user('14600000-0000-4000-8000-000000000090')$$,'42501','PUM_AUTH_BINDING','missing Auth identity cannot finalize a profile');
RESET ROLE;
INSERT INTO auth.users(id,email,email_confirmed_at,encrypted_password,raw_app_meta_data,raw_user_meta_data)
 SELECT (result->>'auth_user_id')::uuid,'created146@example.test',now(),'synthetic-owned-hash','{"_invite_provisioned":true}',jsonb_build_object('_invite_provisioned',true,'_platform_provision_request','14600000-0000-4000-8000-000000000090','_platform_provision_tenant',(SELECT id FROM platform146_tenants WHERE kind='own')::text,'_platform_provision_actor','14600000-0000-4000-8000-000000000001') FROM platform146_results WHERE kind='reserved';
SET LOCAL ROLE authenticated;
SELECT throws_ok($$SELECT public.finalize_platform_user('14600000-0000-4000-8000-000000000090')$$,'42501','PUM_AUTH_BINDING','editable user metadata cannot establish provisioning ownership');
RESET ROLE;
UPDATE auth.users SET raw_app_meta_data=jsonb_build_object('_invite_provisioned',true,'_platform_provision_request','14600000-0000-4000-8000-000000000090','_platform_provision_tenant',(SELECT id FROM platform146_tenants WHERE kind='own')::text,'_platform_provision_actor','14600000-0000-4000-8000-000000000001'),email_confirmed_at=NULL WHERE id=(SELECT (result->>'auth_user_id')::uuid FROM platform146_results WHERE kind='reserved');
SET LOCAL ROLE authenticated;
SELECT throws_ok($$SELECT public.finalize_platform_user('14600000-0000-4000-8000-000000000090')$$,'42501','PUM_AUTH_BINDING','unconfirmed identity cannot finalize initial-password creation');
RESET ROLE;
UPDATE auth.users SET email_confirmed_at=now() WHERE id=(SELECT (result->>'auth_user_id')::uuid FROM platform146_results WHERE kind='reserved');
CREATE TRIGGER fail_platform146_audit BEFORE INSERT ON public.audit_log FOR EACH ROW EXECUTE FUNCTION pg_temp.fail_platform146_audit();
SET LOCAL ROLE authenticated;
SELECT throws_ok($$SELECT public.finalize_platform_user('14600000-0000-4000-8000-000000000090')$$,'P0001','Synthetic platform audit fault','failed creation audit rolls back profile, membership, assignment and completion');
RESET ROLE;
SELECT is((SELECT count(*) FROM public.users WHERE auth_user_id=(SELECT (result->>'auth_user_id')::uuid FROM platform146_results WHERE kind='reserved')),0::bigint,'failed creation leaves no partial application profile');
SELECT is((SELECT count(*) FROM auth.users WHERE id=(SELECT (result->>'auth_user_id')::uuid FROM platform146_results WHERE kind='reserved')),1::bigint,'failed application finalization retains the owned Auth identity for recovery');
DROP TRIGGER fail_platform146_audit ON public.audit_log;
SET LOCAL ROLE authenticated;
INSERT INTO platform146_results VALUES('created',public.finalize_platform_user('14600000-0000-4000-8000-000000000090'));
SELECT ok((public.finalize_platform_user('14600000-0000-4000-8000-000000000090')->>'replayed')::boolean,'unknown finalization outcome can be reconciled idempotently');
RESET ROLE;
SELECT ok((SELECT status='active' AND role='accountant' AND must_change_password AND version=1 FROM public.users WHERE id=(SELECT (result->>'id')::uuid FROM platform146_results WHERE kind='created')),'final profile has the supported role and forced initial password change');
SELECT is((SELECT count(*) FROM public.tenant_memberships WHERE user_id=(SELECT (result->>'id')::uuid FROM platform146_results WHERE kind='created') AND deleted_at IS NULL),1::bigint,'atomic creation adds one active membership');
SELECT is((SELECT count(*) FROM public.user_role_assignments WHERE user_id=(SELECT (result->>'id')::uuid FROM platform146_results WHERE kind='created') AND revoked_at IS NULL AND deleted_at IS NULL),1::bigint,'atomic creation adds one active role assignment');
SELECT is((SELECT count(*) FROM public.audit_log WHERE entity_id=(SELECT (result->>'id')::uuid FROM platform146_results WHERE kind='created') AND action='platform_user_created'),1::bigint,'repeated finalization produces exactly one minimized create audit');
SET LOCAL ROLE authenticated;
RESET ROLE;
UPDATE public.users SET email='retired-profile146@example.test' WHERE id=(SELECT (result->>'id')::uuid FROM platform146_results WHERE kind='created');
SET LOCAL ROLE authenticated;
SELECT is(public.mutate_platform_user('reset_request',(SELECT (result->>'id')::uuid FROM platform146_results WHERE kind='created'),2,'{"reason":"Recovery must target the bound Auth identity"}')->>'email','created146@example.test','password recovery targets canonical confirmed Auth email rather than stale profile email');
SELECT throws_ok($$SELECT public.reserve_platform_user('14600000-0000-4000-8000-000000000092',(SELECT id FROM platform146_tenants WHERE kind='own'),'owner-promote146@example.test','general_manager',NULL)$$,'22023','PUM_INPUT','initial-password creation cannot appoint a new owner through this endpoint');
INSERT INTO platform146_results VALUES('invite',public.issue_platform_user_invite('14600000-0000-4000-8000-000000000093',(SELECT id FROM platform146_tenants WHERE kind='own'),'invite146@example.test','accountant',NULL,'14600000-0000-4000-8000-000000000094',crypt('synthetic-token146',gen_salt('bf')),now()+interval '7 days'));
SELECT ok((public.issue_platform_user_invite('14600000-0000-4000-8000-000000000093',(SELECT id FROM platform146_tenants WHERE kind='own'),'invite146@example.test','accountant',NULL,'14600000-0000-4000-8000-000000000095',crypt('different-retry-token',gen_salt('bf')),now()+interval '7 days')->>'replayed')::boolean,'invitation retries retain the already-issued original token');
RESET ROLE;
CREATE TEMP TABLE platform146_invite_token AS SELECT token_hash FROM public.invites WHERE id=(SELECT (result->>'id')::uuid FROM platform146_results WHERE kind='invite');
GRANT SELECT ON platform146_invite_token TO authenticated;
SET LOCAL ROLE authenticated;
SELECT ok((public.issue_platform_user_invite('14600000-0000-4000-8000-000000000093',(SELECT id FROM platform146_tenants WHERE kind='own'),'invite146@example.test','accountant',NULL,'14600000-0000-4000-8000-000000000094',(SELECT token_hash FROM platform146_invite_token),now()+interval '7 days')->>'send_current_token')::boolean,'lost response reconciliation may send only the exact originally issued token');
SELECT ok(NOT(public.issue_platform_user_invite('14600000-0000-4000-8000-000000000093',(SELECT id FROM platform146_tenants WHERE kind='own'),'invite146@example.test','accountant',NULL,'14600000-0000-4000-8000-000000000095',crypt('new-unrelated-token',gen_salt('bf')),now()+interval '7 days')->>'send_current_token')::boolean,'new retry token cannot be emailed as though it matched the preserved invitation');
RESET ROLE;
SELECT is((SELECT token_id FROM public.invites WHERE id=(SELECT (result->>'id')::uuid FROM platform146_results WHERE kind='invite')),'14600000-0000-4000-8000-000000000094'::uuid,'retry does not invalidate the first invitation link');
SELECT is((SELECT count(*) FROM public.invites WHERE email='invite146@example.test'),1::bigint,'one creation request issues one pending invitation');
SELECT is((SELECT count(*) FROM public.audit_log WHERE entity_id=(SELECT (result->>'id')::uuid FROM platform146_results WHERE kind='invite') AND action='platform_invite_created'),1::bigint,'invitation request audit is idempotent');
SET LOCAL ROLE authenticated;
SELECT throws_ok($$SELECT public.issue_platform_user_invite('14600000-0000-4000-8000-000000000096',(SELECT id FROM platform146_tenants WHERE kind='own'),'gm-invite146@example.test','general_manager',NULL,'14600000-0000-4000-8000-000000000097',crypt('synthetic-token146',gen_salt('bf')),now()+interval '7 days')$$,'22023','PUM_INPUT','platform invitations preserve the managed non-owner role contract');
RESET ROLE;
UPDATE public.tenants SET status='suspended' WHERE id=(SELECT id FROM platform146_tenants WHERE kind='own');
SET LOCAL ROLE authenticated;
SELECT throws_ok($$SELECT public.reserve_platform_user('14600000-0000-4000-8000-000000000098',(SELECT id FROM platform146_tenants WHERE kind='own'),'suspended146@example.test','accountant',NULL)$$,'55000','PUM_TENANT_INACTIVE','platform creation requires an active undeleted target tenant');
SELECT throws_ok($$SELECT public.finalize_platform_user('14600000-0000-4000-8000-000000000090')$$,'55000','PUM_TENANT_INACTIVE','even a completion retry cannot act through a suspended target tenant');
RESET ROLE;
UPDATE public.tenants SET status='active',deleted_at=now() WHERE id=(SELECT id FROM platform146_tenants WHERE kind='own');
SET LOCAL ROLE authenticated;
SELECT throws_ok($$SELECT public.mutate_platform_user('reset_request',(SELECT (result->>'id')::uuid FROM platform146_results WHERE kind='created'),1,'{"reason":"Recovery forbidden while tenant deleted"}')$$,'55000','PUM_TENANT_INACTIVE','password recovery cannot target a deleted tenant');
RESET ROLE;
UPDATE public.tenants SET deleted_at=NULL WHERE id=(SELECT id FROM platform146_tenants WHERE kind='own');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"14600000-0000-4000-8000-000000000003","aal":"aal2"}',true);
SELECT throws_ok($$SELECT public.finalize_platform_user('14600000-0000-4000-8000-000000000090')$$,'42501','PUM_FORBIDDEN','ordinary foreign owner cannot finalize a reserved global creation');
RESET ROLE;
SET LOCAL ROLE service_role;
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"14600000-0000-4000-8000-000000000001","aal":"aal2"}',true);
SELECT throws_ok($$SELECT public.reserve_platform_user('14600000-0000-4000-8000-000000000099',(SELECT id FROM platform146_tenants WHERE kind='own'),'service146@example.test','accountant',NULL)$$,'42501',NULL,'actual service role cannot invoke caller-only creation even with forged authenticated claims');
SELECT throws_ok($$SELECT public.mutate_platform_user('status','14600000-0000-4000-8000-000000000104',4,'{"status":"active","reason":"Service JWT bypass forbidden"}')$$,'42501',NULL,'actual service role cannot invoke caller-only mutations');
RESET ROLE;
SET LOCAL ROLE anon;
SELECT throws_ok($$SELECT public.finalize_platform_user('14600000-0000-4000-8000-000000000090')$$,'42501',NULL,'anonymous role cannot finalize a user');
RESET ROLE;
SELECT * FROM finish();
ROLLBACK;
